import React from "react";
import { FaMobileAlt } from "react-icons/fa";
import { apiPost } from "../common/api";
import Loader from "../common/Loader";
import withRouter from "../common/withRouter";

// صفحه‌ی ورود — شماره موبایل رو می‌گیره و با /login کد پیامک درخواست می‌کنه
class LoginPage extends React.Component {
  constructor(props) {
    super(props);
    this.state = { mobile: "", loading: false, errorMessage: "" };
    this.handleChange = this.handleChange.bind(this);
    this.handleSubmit = this.handleSubmit.bind(this);
  }

  handleChange(e) {
    this.setState({ mobile: e.target.value });
  }

  handleSubmit(e) {
    e.preventDefault();
    const { mobile } = this.state;
    if (!mobile.trim()) return;

    this.setState({ loading: true, errorMessage: "" });

    apiPost("/login", { mobile })
      .then((json) => {
        this.setState({ loading: false });

        if (json.status === "1") {
          // شماره رو برای مرحله‌ی تایید کد نگه می‌داریم
          localStorage.setItem("pending_mobile", mobile);
          this.props.navigate("/verify-code");
        } else {
          this.setState({ errorMessage: json.message || "خطایی رخ داد" });
        }
      })
      .catch(() => {
        this.setState({ loading: false, errorMessage: "ارتباط با سرور برقرار نشد" });
      });
  }

  render() {
    const { mobile, loading, errorMessage } = this.state;

    return (
      <div dir="rtl" lang="fa" className="bg-white min-vh-100">
        {loading && <Loader />}

        <div className="container-fluid px-3 pt-5" style={{ maxWidth: 480, margin: "0 auto" }}>
          <h1 className="fs-6 fw-semibold text-dark text-center mb-4">ورود به سیستم</h1>
                            <img
                                src="../img/aaa.png"
                                alt="logo"
                                className={styles["img-box"]}
                            />
          <form onSubmit={this.handleSubmit}>
            <div className="d-flex align-items-center justify-content-between gap-2 border rounded-3 px-3 py-3 mb-3 bg-white">
              <input
                type="tel"
                placeholder="شماره موبایل"
                value={mobile}
                onChange={this.handleChange}
                className="form-control border-0 shadow-none text-end p-0"
              />
              <FaMobileAlt className="text-secondary" size={18} />
            </div>

            {errorMessage && (
              <div className="text-danger small text-center mb-3">{errorMessage}</div>
            )}

            <button type="submit" className="btn btn-primary w-100 rounded-3 py-3">
              دریافت کد تایید
            </button>
          </form>
        </div>
      </div>
    );
  }
}

export default withRouter(LoginPage);
